import View from "../framework/View";
import Mesh from "../framework/Mesh";

export default class ViewAnimationTarget extends View {

	constructor(transforms) {

		super(transforms, require("../../shaders/save.vert"), require("../../shaders/save.frag"));

		var positions = [];
		var coords = [];
		// var indices = [0, 1, 2, 0, 2, 3];
		var indices = [];
		var colors = [];
		var radians = [];

		// positions.push([1-.5,-1+.5,0]);

		var detail = window.NS.GL.params.detail;
		var totDetail = detail * detail;
		var offset = .5;

		var index = 0;

		
		// var circlePos = this.createCirclePos(totDetail);
		var pointData = this.createPointData(totDetail);
		// var pointData = this.createSphere();


		var y = 1 - (2 / (detail * 2));
		var step = 2 / detail;

		for (var row=0;row<detail;row++){
			
			var x = -1 + (2 / (detail * 2));
			for (var col=0;col<detail;col++){

				positions.push([x, y, 0]);
				indices.push(index);
				colors.push([ pointData[index][0], pointData[index][1], pointData[index][2] ]);
		
				x += step;
				index++;

			}

			y -= step;
		}

		this.mesh = new Mesh(positions.length, indices.length, this.gl.POINTS);
		this.mesh.bufferVertex(positions);
		this.mesh.bufferIndices(indices);
		this.mesh.bufferData(colors, "aVertexColor", 3);
	}

	createPointData(totDetail) {

		
		var pointData = [];
		var nrRows = window.NS.GL.params.detail;
		var nrCols = window.NS.GL.params.detail;
		

		for (var row=0;row<nrRows;row++){

			var y = row/nrRows;

			for (var col=0;col<nrCols;col++){

				var x = col/nrCols;
				pointData.push([x, y, 2]);
			}
		}
		



		return pointData;
	}

	createSphere() {

		var latitudeBands = window.NS.GL.params.detail-1;
        var longitudeBands = window.NS.GL.params.detail-1;
        var radius = 1;

      	var pos = [];
        for (var latNumber=0; latNumber <= latitudeBands; latNumber++) {
            var theta = latNumber * 2 * Math.PI / latitudeBands;
            var sinTheta = Math.sin(theta);
            var cosTheta = Math.cos(theta);

            for (var longNumber=0; longNumber <= longitudeBands; longNumber++) {
                var phi = longNumber * 2 * Math.PI / longitudeBands;
                var sinPhi = Math.sin(phi);
                var cosPhi = Math.cos(phi);

                var x = cosPhi * sinTheta;
                var y = cosTheta;
                var z = sinPhi * sinTheta;

                // var u = 1 - (longNumber / longitudeBands);
                // var v = 1 - (latNumber / latitudeBands);

                var vector = vec3.fromValues(radius * x, radius * y, radius * z);

                // if (pos.length > 50) continue;

                // console.log(pos.length);
             	pos.push(vector);
             	
            }
        }
       
        return pos;
	}

	

	render() {

		// this.transforms.push();

		this.shader.bind();

		this.draw(this.mesh);

		// this.transforms.pop();
	}
}



