import Scene from "./framework/Scene";
import ViewSave from "./views/ViewSave";
import ViewAnimationTarget from "./views/ViewAnimationTarget";
import ViewCopy from "./views/ViewCopy";
import ViewCal from "./views/ViewCal";
import ViewMap from "./views/ViewMap";
import ViewBlur from "./views/ViewBlur";
import MouseInteractor from "./framework/MouseInteractor";
import KeyboardInteractor from "./framework/KeyboardInteractor";
import SceneTransforms from "./framework/SceneTransforms";
import Framebuffer from "./framework/Framebuffer";
import Texture from "./framework/Texture";
import SpectrumAnalyser from "./framework/SpectrumAnalyser";

export default class SceneMain extends Scene {
	constructor() {

		super();
		this.onResize();
		window.addEventListener('resize', () => {
			this.onResize();
		});

		
		this.noticeEl = document.createElement('h2');
		this.noticeEl.className = 'notice';
		this.noticeEl.innerHTML = 'TURN UP THE VOLUME ON YOUR SPEAKERS !';

		setTimeout( () => {

			this.noticeEl.style.display = 'none';
		},5000);

		document.body.appendChild(this.noticeEl);

		this.viewsCreated = false;

		this.animationTimestamp = Date.now();
		this.animationCounter = 0;
		this.animationDir = 1;

		if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) {
		  alert("enumerateDevices() not supported.");
		  return;
		}

		
		navigator.getUserMedia = navigator.getUserMedia || navigator.webkitGetUserMedia || navigator.mozGetUserMedia || navigator.msGetUserMedia;

		var self = this;
		navigator.mediaDevices.enumerateDevices()
		.then(devices => {


			this.gotDevices(devices);
		
		})
		

		this.hasSaved = false;

		this.camera.setPosition(new Array(0.0, 0.0, 0.0));
		this.camera.setLookAtPoint(vec3.fromValues(0.0, 0.0, 1.0));

		this.mouseInteractor = new MouseInteractor(this.camera, this.canvas);
		this.mouseInteractor.setup();

		this.keyboardInteractor = new KeyboardInteractor(this.camera, this.canvas);
		this.keyboardInteractor.setup();

		this.transforms = new SceneTransforms(this.canvas);

		this.orthoTransforms = new SceneTransforms(this.canvas);
		
		

	}

	gotDevices(devices){

		
		var constraints = {
			audio: {
			  optional: [{
				sourceId: undefined
			  }]
			},
			video: {
			  optional: [{
				sourceId: undefined
			  }]
			}
		}

		for (var device of devices){
			if (device.kind == 'audioinput')
				constraints.audio.optional[0]['sourceId'] = device.deviceId;
			else if (device.kind == 'videoinput')
				constraints.video.optional[0]['sourceId'] = device.deviceId;
		}

	
		if (navigator.getUserMedia){
			navigator.getUserMedia(constraints, this.gotStream.bind(this) , this.streamErr.bind(this));
		}
		
	}

	gotStream(stream) {


		var audioCtx = new AudioContext();
		var micStreamNode = audioCtx.createMediaStreamSource(stream);

		this.analyser = new SpectrumAnalyser();
		this.analyser.setup(audioCtx, this.onAudioData, this);

		this.analyser.connect(micStreamNode);
		this.analyser.update();

		this.video = document.createElement('video');
		this.video.src = window.URL.createObjectURL(stream);
		// document.body.appendChild(this.video);
		this.video.width    = 256;
		this.video.height   = 256;
		this.video.autoplay = true;
		this.video.volume = 0;
		this.video.addEventListener('canplaythrough', () => {
			
			this.initTextures();
			this.initViews();


		});
	
		
		
	}

	streamErr() {

	}

	onAudioData(data) {

		var subbands = [2, 3, 4, 6, 8, 20, 30, 40, 50, 55, 60];

		this.latestAudio = data[0][subbands[5]]/5;
	}

	initTextures() {


		this._videoTexture = new Texture(this.video, false);
		
		var size = window.NS.GL.params.detail;

		this.fboCurrent = new Framebuffer(size, size, this.gl.NEAREST, this.gl.NEAREST, this.gl.FLOAT);
		this.fboCurrent.id = 'fboCurrent';

		this.fboTarget = new Framebuffer(size, size, this.gl.NEAREST, this.gl.NEAREST, this.gl.FLOAT);
		this.fboTarget.id = 'fboTarget';

		this.fboDataCurrent = new Framebuffer(size, size, this.gl.NEAREST, this.gl.NEAREST, this.gl.FLOAT);
		this.fboDataCurrent.id = 'fboDataCurrent';

		this.fboDataTarget = new Framebuffer(size, size, this.gl.NEAREST, this.gl.NEAREST, this.gl.FLOAT);
		this.fboDataTarget.id = 'fboDataTarget';

		this._blurVFBO = new Framebuffer(this.gl.viewportWidth, this.gl.viewportHeight, this.gl.NEAREST, this.gl.NEAREST, this.gl.UNSIGNED_BYTE);
		this._postPreFBO = new Framebuffer(this.gl.viewportWidth, this.gl.viewportHeight, this.gl.NEAREST, this.gl.NEAREST, this.gl.UNSIGNED_BYTE);
	
	}

	initViews() {

		this.viewsCreated = true;

		this._vAnimationTarget = new ViewAnimationTarget(this.orthoTransforms);

		this._vSave = new ViewSave(this.orthoTransforms);

		this._vCopy = new ViewCopy(this.orthoTransforms);

		this._vCal = new ViewCal(this.orthoTransforms);

		this._vMap = new ViewMap(this.transforms);

		this._vBlurVert = new ViewBlur(this.orthoTransforms, require("../shaders/verticalGaussianBlur.frag"));

		this._vBlurHoriz = new ViewBlur(this.orthoTransforms, require("../shaders/horizontalGaussianBlur.frag"));
		
	}

	update() {

		super.update();

	}

	render() {

		if (!this.viewsCreated) return;

		this.gl.disable(this.gl.DEPTH_TEST);

		this.gl.enable(this.gl.BLEND);

		var now = Date.now();
		// var diff = now - this.animationTimestamp;
		this.animationCounter += this.animationDir;
		// console.log(diff);
		if (this.animationCounter > 1000)
			this.animationDir = -1;
		else if (this.animationCounter < 0)
			this.animationDir = 1;
		
		if (!this.hasSaved){

			this.animationTimestamp = Date.now();

			this.orthoTransforms.setCamera(this.orthoCamera);

			this.fboCurrent.bind();
			this.gl.viewport(0, 0, this.fboCurrent.width, this.fboCurrent.height);
			this.gl.clearColor( 0.0, 0.0, 0.0, 1 );
			this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);
			
			this._vSave.render();
			this.fboCurrent.unbind();

			

			this.fboTarget.bind();
			this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);
			this.fboTarget.unbind();


			this.fboDataCurrent.bind();
			this.gl.viewport(0, 0, this.fboDataCurrent.width, this.fboDataCurrent.height);
			this.gl.clearColor( 0.0, 0.0, 0.0, 1 );
			this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);

			this._vAnimationTarget.render();
			this.fboDataCurrent.unbind();

			// this.gl.viewport(0,0,window.innerWidth, window.innerHeight);

			// this._vCopy.render(this.fboCurrent.getTexture());



			this.hasSaved = true;
			
			return;
		
		}

		this._videoTexture.updateTexture(this.video);

	
		this.orthoTransforms.setCamera(this.orthoCamera);

		this.gl.viewport(0, 0, this.fboCurrent.width, this.fboCurrent.height);

		this.fboTarget.bind();

		this._vCal.render(this.fboCurrent.getTexture(), this.fboDataCurrent.getTexture(), Math.random(), this.latestAudio);

		this.fboTarget.unbind();

		// this.gl.viewport(0, 0, window.innerWidth, window.innerHeight);

		
		// this._vCopy.render(this.fboTarget.getTexture());



		// return;





		this.gl.viewport(0, 0, this.gl.viewportWidth, this.gl.viewportHeight);

		this.gl.clearColor( 0, 0, 0, 1 );
		this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);


		this.transforms.push();
		this.transforms.setCamera(this.camera);

		this.camera.apply(this.gl.viewportWidth / this.gl.viewportHeight);
		this.transforms.calculateModelView();

		// this._postPreFBO.bind();
		// this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);
		this._vMap.render(this.fboTarget.getTexture(), this._videoTexture, this.latestAudio);

		// this._postPreFBO.unbind();

		this.transforms.pop();


		//POST-Processing
		// this._blurVFBO.bind();
		// this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);

		// this._vBlurVert.render(this._postPreFBO.getTexture());

		// this._blurVFBO.unbind();

		// // this._blurHFBO.bind();
		// // gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

		// this._vBlurHoriz.render(this._blurVFBO.getTexture());

		// this._blurHFBO.unbind();

		


	
		

		this.swapFbos();

	}

	swapFbos() {
		
		var tmp = this.fboTarget;
		this.fboTarget = this.fboCurrent;
		this.fboCurrent = tmp;
	};


}


