import View from "../framework/View";
import Mesh from "../framework/Mesh";

export default class ViewBlur extends View {
	
	constructor(transforms, fragShader) {

		super(transforms, require("../../shaders/copy.vert"), fragShader);

		var positions = [];
		var coords = [];
		// var indices = [0, 1, 2, 0, 2, 3];
		
		var indices = [0, 1, 2, 0, 2, 3];

		positions.push([-1,	-1,  0]);
		positions.push([ 1,	-1,  0]);
		positions.push([ 1,	 1,  0]);
		positions.push([-1,	 1,  0]);

		coords.push([0, 0]);
		coords.push([1, 0]);
		coords.push([1, 1]);
		coords.push([0, 1]);

		this.mesh = new Mesh(positions.length, indices.length, this.gl.TRIANGLES);
		this.mesh.bufferVertex(positions);
		this.mesh.bufferTexCoords(coords);
		this.mesh.bufferIndices(indices);
	}

	render(texture) {

		this.shader.bind();
		this.shader.uniform("sceneTexture", "uniform1i", 0);

		this.shader.uniform("rt_w","uniform1f",window.innerWidth);
		this.shader.uniform("rt_h","uniform1f",window.innerHeight);

		
		texture.bind(this.shader, 0);
		this.draw(this.mesh);
	} 
}


