import View from "../framework/View";
import Mesh from "../framework/Mesh";

export default class ViewSave extends View {

	constructor(transforms) {

		super(transforms, require("../../shaders/save.vert"), require("../../shaders/save.frag"));

		var positions = [];
		var coords = [];
		// var indices = [0, 1, 2, 0, 2, 3];
		var indices = [];
		var colors = [];

		// positions.push([1-.5,-1+.5,0]);

		var detail = window.NS.GL.params.detail;
		var totDetail = detail * detail;
		var offset = .5;

		var index = 0;

		
		
		var y = 1 - (2 / (detail * 2));
		var step = 2 / detail;

		for (var row=0;row<detail;row++){
			
			var x = -1 + (2 / (detail * 2));
			for (var col=0;col<detail;col++){

				positions.push([x, y, 0]);
				indices.push(index);
				// colors.push( this.pointData[index] );
				colors.push([(Math.random()*10)/10, (Math.random()*10)/10, (Math.random()*2)/2]);


				x += step;
				index++;

			}

			y -= step;
		}

		this.mesh = new Mesh(positions.length, indices.length, this.gl.POINTS);
		this.mesh.bufferVertex(positions);
		this.mesh.bufferIndices(indices);
		this.mesh.bufferData(colors, "aVertexColor", 3);
	}

	

	createCirclePos(totDetail){

		var nrCircles = 32;
		var pointsPerRow = totDetail / nrCircles;

		var currentCircleIdx = 0;

		var pos = [];
		var y = -4;
		for (var i=0;i<totDetail;i++){

			var rad = this._getRadius(currentCircleIdx, nrCircles);
			var pointPos = this._getCirclePos(rad, i, totDetail);

			pos.push([ pointPos[0], y, pointPos[1] ]);

			if (i % pointsPerRow == 0){
				if (i == 0) continue;

				currentCircleIdx++;

				
				
			}

			y += .003;


		}

		return pos;
	}

	_getRadius(circleIdx, totCircles) {

		return Math.sin((circleIdx / totCircles) * Math.PI)
	}

	_getCirclePos(rad, index, totDetail) {

		var centerX = 0;
		var centerZ = 30;
		var rad = Math.sin((index/totDetail) * Math.PI ) * 20;

		// console.log(rad);

		var theta = ( 360 / totDetail ) * index;
		var x = centerX + rad * Math.cos(theta);
		var z = centerZ + rad * Math.sin(theta);

		return [x, z];

	}

	render() {

		// this.transforms.push();

		this.shader.bind();

		this.draw(this.mesh);

		// this.transforms.pop();
	}
}



